//! Emit the shared native absence classifier with exact package/module provenance.
pub fn render(arguments: &[String]) -> Result<String, Box<dyn std::error::Error>> {
    let [loader, importer, stem] = arguments else {
        return Err(
            "native-absence mode expects loader specifier, importer and companion stem".into(),
        );
    };
    let loader = serde_json::to_string(loader)?;
    let importer = serde_json::to_string(importer)?;
    let stem = serde_json::to_string(stem)?;
    Ok(format!(
        "// Generated by the private Rust CLI from the shared original-error provenance classifier.\nconst importerUrl = new URL({importer}, import.meta.url).href;\nconst loaderSpecifier = {loader};\nconst loaderUrl = new URL(loaderSpecifier, importerUrl).href;\nconst companionStem = {stem};\n{}",
        include_str!("native-absence.template.ts")
    ))
}
